insert into services (id, name, kind, duration_min, price, is_trial, first_time_only, return_days, image, description, sort, active) values
  ('nail_trial', 'はじめてのジェルネイル体験', 'timed', 60, 2500, true, true, 21, 'nail_trial.png', '初めての方限定の体験プラン。カラーを1色選んで、ワンカラーのジェルを塗ります。ケアとオフ込み。', 1, true),
  ('nail_onecolor', 'ワンカラージェル', 'timed', 60, 5500, false, false, 28, 'nail_onecolor.png', 'お好きな色を1色で仕上げる、定番のジェル。ケア込み。', 2, true),
  ('nail_art', 'アートネイル', 'timed', 90, 7800, false, false, 28, 'nail_art.png', 'ラメ・グラデーション・フレンチなどのデザインを、写真を見ながら相談できます。', 3, true),
  ('nail_foot', 'フットジェル', 'timed', 75, 6600, false, false, 35, 'nail_foot.png', '足の爪のケアとジェル。夏以外も長持ちするので人気です。', 4, true),
  ('nail_off', 'オフ＋ハンドケア', 'timed', 45, 3300, false, false, 28, 'nail_off.png', 'ジェルを溶かして落とし、爪と甘皮を整えます。つけ替えの前にも。', 5, true),
  ('nail_care', 'ハンドケア（甘皮・保湿）', 'timed', 30, 2200, false, false, 21, 'nail_care.png', '甘皮の処理と保湿パック。ジェルなしで爪をいたわりたい方に。', 6, true),
  ('nail_repair', '付け替え・リペア', 'timed', 30, 1650, false, false, 21, 'nail_repair.png', '欠けや浮きが出た1〜2本の補修。ご来店日の当日お問い合わせもどうぞ。', 7, true);
