insert into customers (id, name, kana, phone, email, note, caution, created_at, active) values
  ('c01', '岡田 結衣', 'おかだ ゆい', '090-0000-1137', 'yui.okada@example.com', '体験から通常メニューへ。ベージュ系のワンカラーが好み。', '', '2026-09-11 13:00:00+09:00'::timestamptz, true),
  ('c02', '高木 沙織', 'たかぎ さおり', '090-0000-1174', 'saori.takagi@example.com', '体験から通常メニューへ。短めの爪が好き。仕事柄、派手なアートは避ける。', '爪が薄く割れやすい。ファイルはやさしく。', '2026-09-11 12:25:00+09:00'::timestamptz, true),
  ('c03', '宮崎 紗希', 'みやざき さき', '090-0000-1211', 'saki.miyazaki@example.com', '体験から通常メニューへ。次回はアートに挑戦したいとのこと。', '', '2026-09-29 12:30:00+09:00'::timestamptz, true),
  ('c04', '小川 夏帆', 'おがわ かほ', '090-0000-1248', 'kaho.ogawa@example.com', '体験のあと1回来店。そろそろ次の時期。', '', '2026-08-30 14:05:00+09:00'::timestamptz, true),
  ('c05', '千葉 真由', 'ちば まゆ', '090-0000-1285', 'mayu.chiba@example.com', '体験から通常メニューへ。フットも気になっている。', 'ジェルで赤みが出たことあり。パッチテスト済み。', '2026-09-22 12:35:00+09:00'::timestamptz, true),
  ('c06', '森山 友里', 'もりやま ゆり', '090-0000-1322', 'yuri.moriyama@example.com', '友人の紹介で体験。月1回のペースで通う予定。', '', '2026-10-03 18:15:00+09:00'::timestamptz, true),
  ('c07', '金子 朋美', 'かねこ ともみ', '090-0000-1359', 'tomomi.kaneko@example.com', '体験のみ。仕上がりは好評で、次回の予約は未定。', '', '2026-10-05 10:10:00+09:00'::timestamptz, true),
  ('c08', '土屋 美咲', 'つちや みさき', '090-0000-1396', '', '体験のみ。ネイルは初めて。', '', '2026-10-17 18:30:00+09:00'::timestamptz, true),
  ('c09', '横山 菜々子', 'よこやま ななこ', '090-0000-1433', 'nanako.yokoyama@example.com', '体験を無断欠席。連絡は夜のほうが通じやすい。', '', '2026-10-08 18:20:00+09:00'::timestamptz, true),
  ('c10', '川口 志保', 'かわぐち しほ', '090-0000-1470', 'shiho.kawaguchi@example.com', '体験を予約。初めてのネイル。', '', '2026-11-04 14:00:00+09:00'::timestamptz, true),
  ('c11', '寺田 莉子', 'てらだ りこ', '090-0000-1507', 'riko.terada@example.com', '体験を予約。お出かけ前の下見で来店予定。', '', '2026-11-07 11:50:00+09:00'::timestamptz, true),
  ('c12', '吉田 里奈', 'よしだ りな', '090-0000-1544', 'rina.yoshida@example.com', '常連。毎回グラデーション。ラメ多めが好き。', '妊娠中。薬剤の香りに配慮。', '2026-06-06 17:35:00+09:00'::timestamptz, true),
  ('c13', '木村 琴音', 'きむら ことね', '090-0000-1581', 'kotone.kimura@example.com', 'ワンカラー派。無断欠席が1回あり、前日に確認の連絡をする。', '爪のまわりが乾燥しやすい。保湿多め。', '2026-06-03 11:10:00+09:00'::timestamptz, true),
  ('c14', '内藤 美穂', 'ないとう みほ', '090-0000-1618', '', '来店の間隔が空きぎみ。', '', '2026-05-01 13:30:00+09:00'::timestamptz, true),
  ('c15', '和田 彩香', 'わだ あやか', '090-0000-1655', 'ayaka.wada@example.com', 'アートが好き。季節ごとにデザインを変える。', '二枚爪ぎみ。', '2026-03-28 17:25:00+09:00'::timestamptz, true),
  ('c16', '久保 優子', 'くぼ ゆうこ', '090-0000-1692', 'yuko.kubo@example.com', 'フットケア中心。', '', '2026-01-28 14:15:00+09:00'::timestamptz, true),
  ('c17', '西村 瑞希', 'にしむら みずき', '090-0000-1729', 'mizuki.nishimura@example.com', '早番の仕事。朝いちの枠を希望。', '左手の腱鞘炎。手を長く反らさない。', '2026-01-23 10:15:00+09:00'::timestamptz, true),
  ('c18', '青木 香織', 'あおき かおり', '090-0000-1766', 'kaori.aoki@example.com', 'お子さん連れのことがある。静かな時間帯が合う。', '', '2026-06-28 13:45:00+09:00'::timestamptz, true),
  ('c19', '児玉 恵', 'こだま めぐみ', '090-0000-1803', 'megumi.kodama@example.com', 'オフと付け替えで来店。', '', '2026-04-15 11:00:00+09:00'::timestamptz, true),
  ('c20', '野口 明日香', 'のぐち あすか', '090-0000-1840', 'asuka.noguchi@example.com', 'デザインは持参の写真から決める。', '', '2026-07-21 10:15:00+09:00'::timestamptz, true),
  ('c21', '石井 奈緒', 'いしい なお', '090-0000-1877', '', '短時間で済ませたい。ハンドケア中心。', 'ジェルのにおいが苦手。換気を希望。', '2026-06-20 09:25:00+09:00'::timestamptz, true),
  ('c22', '坂本 由美', 'さかもと ゆみ', '090-0000-1914', 'yumi.sakamoto@example.com', '月2回の常連。', '', '2026-04-20 16:35:00+09:00'::timestamptz, true),
  ('c23', '橋本 千夏', 'はしもと ちなつ', '090-0000-1951', 'chinatsu.hashimoto@example.com', 'ネイルチップの相談あり。', '', '2026-02-13 17:50:00+09:00'::timestamptz, true),
  ('c24', '井上 麻衣', 'いのうえ まい', '090-0000-1988', 'mai.inoue@example.com', 'シンプルな縦グラデーション。', '深爪ぎみ。長さは出さない。', '2026-04-08 19:05:00+09:00'::timestamptz, true),
  ('c25', '島田 理恵', 'しまだ りえ', '090-0000-2025', 'rie.shimada@example.com', '夜の枠を好む。', '', '2026-05-25 14:45:00+09:00'::timestamptz, true);
